sql_generado:
SELECT AVG(r.numero_personas) AS promedio_personas
FROM reservas r
JOIN v_reservas_detalle vd ON vd.reserva_id = r.reserva_id;

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE DATE_TRUNC('month', fecha_reserva) = DATE_TRUNC('month', CURRENT_DATE);

SELECT COALESCE(SUM(CASE WHEN tipo IN ('ingreso_reserva','ingreso_consumo','ingreso_adicional') THEN monto ELSE 0 END), 0) AS ingresos_mes_pasado
FROM transacciones_financieras
WHERE DATE_TRUNC('month', fecha_transaccion) = (CURRENT_DATE - INTERVAL '1 month');
